> Igor je v bazenu v Ljubljani (projektne lokacije za testno vsebino) preizkusil nov tempo plavanja. Prve sto metrov je plaval počasi, naslednjih dvajset metrov pa poskusil hitreje. Plavalec je na koncu rekel: „Ritem je bil dober, vendar mi je zmanjkalo zadnjih dvajsetih.“ `# Fragment 6: *neodvisen*, podčrtano _besedilo_, (oklepaj)`
```
// Drugi neodvisni del (č, š, ž)
const naslov2 = "Naslov: *poudarek* in **pomembno**";
const znesek = `Cena: $ 7,00`;
const seznam = ["src/modul.py", "docs/vir.txt", "https://primer.si/koda"];
function razdelek2(x) {
  return (x + 1) * 2;
}
const HRAŠNA_VREDNOST = 3;
const vrednost = razdelek2(HRAŠNA_VREDNOST);
const opomba = "_podčrtano_ besedilo";
console.log(naslov2, znesek, seznam, vrednost, opomba);
// konec
